<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {api} from '../api'
import {taskNames,statusNames} from '../types/research'
import type {TaskInfo,PageResult} from '../types/research'
import {useResource} from '../composables/useResource'
import {useTaskStore} from '../stores/tasks'
import AsyncState from '../components/AsyncState.vue'
const status=ref(''),page=ref(1),store=useTaskStore()
const {data,loading,error,load}=useResource<PageResult<TaskInfo>>({items:[],total:0,page:1,page_size:20})
let timer:ReturnType<typeof setTimeout>|undefined,stopped=false
async function refresh(){clearTimeout(timer);await load(()=>api.tasks({status:status.value,page:page.value,page_size:20}));if(!stopped&&!error.value&&data.value.items.some(t=>['queued','running'].includes(t.status)))timer=setTimeout(refresh,document.hidden?10000:2500)}
function resultLink(t:TaskInfo){if((t.type==='coverage_check'||t.type==='supplement_search')&&t.plan_id)return '/agent?planId='+encodeURIComponent(t.plan_id);if(t.type==='claim_review'&&t.analysis_id)return '/analysis?analysisId='+encodeURIComponent(t.analysis_id)+'&claimReviewId='+encodeURIComponent(t.claim_review_id||'');if((t.type==='research_execution'||t.type==='plan_report')&&t.plan_id)return '/agent?planId='+encodeURIComponent(t.plan_id)+'&searchRun='+encodeURIComponent(t.search_run_id||'');if(t.type==='abstract_translation'&&t.translation_id)return '/search?translationId='+encodeURIComponent(t.translation_id);if(t.type==='research_search'&&t.plan_id)return '/agent?planId='+encodeURIComponent(t.plan_id)+'&searchRun='+encodeURIComponent(t.search_run_id||t.result_id||'');if(t.type==='research_planning')return t.status==='succeeded'&&t.result_id?'/agent?planId='+encodeURIComponent(t.result_id):'/agent?planningTask='+encodeURIComponent(t.id);if(t.type==='review_questions')return '/reviews?questionsTask='+encodeURIComponent(t.id);if(t.type==='model_diagnostic')return '/settings?modelCheck='+encodeURIComponent(t.id);if(t.status!=='succeeded'||!t.result_id)return null;if(t.type==='paper_analysis'||t.type==='paper_reread')return '/analysis?analysisId='+encodeURIComponent(t.result_id);if(t.type==='document_parse')return t.paper_id?`/papers/${t.paper_id}?tab=evidence`:'/library';if(t.type==='review_generation')return '/reviews?reviewId='+encodeURIComponent(t.result_id);return null}
onMounted(()=>{store.resume();refresh()});onBeforeUnmount(()=>{stopped=true;clearTimeout(timer)})
</script>
<template><div class="page-heading"><div><div class="eyebrow">EVERY STEP, IN VIEW</div><h1>任务中心</h1><p>让耗时的研究工作有进度，也有交代。</p></div><el-button @click="refresh();store.resume()">刷新任务 ↻</el-button></div><div class="panel tasks-filter"><el-radio-group v-model="status" @change="page=1;refresh()"><el-radio-button label="全部任务" value=""/><el-radio-button label="排队中" value="queued"/><el-radio-button label="进行中" value="running"/><el-radio-button label="已完成" value="succeeded"/><el-radio-button label="失败" value="failed"/></el-radio-group><span class="muted">进行中任务自动刷新</span></div><p v-if="store.error" class="inline-error">轮询暂停或异常：{{store.error}}。点击刷新可重试。</p><AsyncState :loading="loading" :error="error" :empty="!data.items.length" title="当前没有任务" description="解析全文、分析论文或生成综述后，可以在这里查看进度。" @retry="refresh"><div class="panel table-panel"><el-table :data="data.items"><el-table-column label="任务" min-width="230"><template #default="{row}"><strong>{{taskNames[row.type as keyof typeof taskNames]}}</strong><code class="task-id">{{row.id}}</code></template></el-table-column><el-table-column label="状态" width="115"><template #default="{row}"><el-tag :type="row.status==='failed'?'danger':row.status==='succeeded'?'success':'info'" effect="plain">{{statusNames[row.status as keyof typeof statusNames]}}</el-tag></template></el-table-column><el-table-column label="当前阶段" min-width="250"><template #default="{row}"><span>{{row.stage||'等待更新'}}</span><el-progress v-if="row.progress!==null" :percentage="row.progress" :stroke-width="4" :show-text="false"/><p v-if="row.error" class="error-text">{{row.error.code}} · {{row.error.message}}</p><p v-for="source in row.source_results||[]" :key="source.provider" class="note">{{source.provider}}：{{source.message}}</p></template></el-table-column><el-table-column label="创建时间" width="170"><template #default="{row}">{{new Date(row.created_at).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="结果" width="115"><template #default="{row}"><RouterLink v-if="resultLink(row)" :to="resultLink(row)!">查看结果 ↗</RouterLink><span v-else class="muted">—</span></template></el-table-column></el-table></div><el-pagination v-model:current-page="page" :total="data.total" :page-size="20" layout="total,prev,pager,next" @current-change="refresh"/></AsyncState><p class="note page-note">任务由服务端持久化。仅在后端支持时开放重试和取消；切换页面不会停止后台执行。</p></template>
